import { fileURLToPath } from "node:url";
import { migrate as drizzleMigrate } from "drizzle-orm/node-postgres/migrator";
import { dbMayFail, getDb } from "./client";

export const MIGRATIONS_FOLDER = fileURLToPath(new URL("./migrations", import.meta.url));

/**
 * Apply pending migrations from src/db/migrations (generated by
 * `pnpm datastore:generate`). Runs in-process with drizzle-orm's migrator,
 * so it can be called from scripts, test setup, or a deploy step.
 */
export const migrate = () =>
  dbMayFail(() => drizzleMigrate(getDb(), { migrationsFolder: MIGRATIONS_FOLDER }), "db:migrate");
